class NomTarifa extends BaseNomTarifa {

    /**
     * Obtener un listado de los datos de las tarifas.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los tipos de nómina.
     */
    public static function obtenerListadoTarifa($inicio = 0, $limite = 1000) {
        //Devolviendo el listado de las tarifas en forma de arreglo.
        $query = new Doctrine_Query ();
        $result = (($inicio != null) and ($limite != null))?
        $query->from('NomTarifa')
            ->orderBy('denominacion')
            ->limit($limite)
            ->offset($inicio)
            ->fetchArray():
        $query->from('NomTarifa')
            ->orderBy('denominacion')
            ->fetchArray();
        return $result;
    }

    /**
     * Obtener la cantidad total de tarifas.
     * 
     * @return int      Cantidad total de tarifas.
     */
    public static function obtenerCantidadTotalTarifa() {

        //Devolviendo la cantidad total de tarifas.
        return Doctrine_Query::create()->select('COUNT(idtarifa) AS cantidad')
                        ->from('NomTarifa')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener la tarifa dado el identificador.
     * 
     * @param int $idtarifa       Identificador dela tarifa.
     * @return NomTarifa          Objeto tarifa (clase del dominio).
     */
    public static function obtenerObjTarifaDadoId($idtarifa) {
        return Doctrine::getTable('NomTarifa')->find($idtarifa);
    }
	
	/**
     * Obtener todas las tarifas.
     * 
     * @return array    Listado de los datos de las tarifas.
     */
    public static function obtenerTodasTarifas() {

        //Devolviendo el listado de las tarifas en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomTarifa')
				->orderBy('denominacion')
                ->fetchArray();
    }

	/**
     * Obtener si existe una tarifa a partir de la denominación.
     * 
	 * @param int $idtarifa    		Identificador de la tarifa.
     * @param string $denom    	 	Denominación de la tarifa.
	 *
     * @return boolean    			Si existe la tarifa.
     */
    public static function existeTarifa($idtarifa, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idtarifa) AS cantidad')
                        ->from('NomTarifa')
						->where("denominacion ilike ?", $denom);
		if($idtarifa){
			$query->addWhere('idtarifa <> ?', $idtarifa);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	 
	 
	 
	 
	
	
	
	
	
	
	
	


/***********************VER DESDE AQUI*******************************************************/    
    public static function obtenerDenomXId($idtarifa) {
        return Doctrine_Query::create()->select('p.denominacion AS denominacion')
                        ->from('NomTarifa p')
                        ->where('p.idtarifa = ?', array($idtarifa))
                        ->fetchOne()
                        ->denominacion;
   }
   
   public static function existeDenominacionTarifa($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomTarifa p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }


    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idtarifa = null)
    {
        try {
            $query = Doctrine_Query::create();
            $query->from('NomTarifa')
                ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
                ->andWhere("denominacion ilike '$denom'");
            if (!empty($idtarifa)) {
                $query->andWhere("idtarifa <> ?", $idtarifa);
            }
            $result = $query->count();
            if ($result > 0) {
                return true;
            } else {
                return false;
            }
        } catch (Doctrine_Exception $e) {
            throw $e;
        }
    }
}
